import {projectBuildingPoint} from './building-footprints.js?v=business-site-analysis-2';
import {materialSurfaceColor,drawMaterialDetail} from './building-materials.js?v=business-site-analysis-2';
export const BLOCK_GRID_SIZE=10;
export function validateBuildingBlocks(value){if(!Array.isArray(value)||value.length!==100||!Array.from(value).every(h=>Number.isInteger(h)&&h>=0&&h<=24)||!value.some(h=>h>0))throw Error('A block layout needs 100 heights from 0–24 and at least one occupied square.');return [...value];}
export function towerToBlocks(d){return Array.from({length:100},(_,i)=>{const x=i%10+.5-5,y=Math.floor(i/10)+.5-5;if(Math.abs(x)>d.width/2||Math.abs(y)>d.depth/2)return 0;return d.roof==='step'&&(Math.abs(x)>d.width*.35||Math.abs(y)>d.depth*.35)?Math.ceil(d.floors*.65):d.floors;});}
export function paintBuildingBlock(blocks,x,y,height){if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=10||y>=10||!Number.isInteger(height)||height<0||height>24)throw Error('Choose a grid square and a height from 0–24.');const next=[...blocks];next[y*10+x]=height;return next;}
export function buildingBlockFaces(blocks,rotation=0,footprint={width:1,height:1}){const rot=((rotation%4)+4)%4,turn=(x,y)=>rot===0?[x,y]:rot===1?[-y,x]:rot===2?[-x,-y]:[y,-x],visible=[[1,2],[0,1],[0,3],[2,3]][rot],directions=[[0,-1],[1,0],[0,1],[-1,0]],faces=[];
 const cells=blocks.map((height,i)=>({height,x:i%10,y:Math.floor(i/10)})).filter(t=>t.height).sort((a,b)=>{const p=turn(a.x*footprint.width,a.y*footprint.height),q=turn(b.x*footprint.width,b.y*footprint.height);return p[0]+p[1]-q[0]-q[1]||p[0]-q[0];});
 for(const cell of cells){const {x,y,height}=cell,x0=(x-5)*.085,y0=(y-5)*.085,corners=[[x0,y0],[x0+.085,y0],[x0+.085,y0+.085],[x0,y0+.085]],top=.12+height*.14;
  for(const side of visible){const [dx,dy]=directions[side],nx=x+dx,ny=y+dy,neighbor=nx<0||ny<0||nx>=10||ny>=10?0:blocks[ny*10+nx];if(neighbor>=height)continue;const a=corners[side],b=corners[(side+1)%4],bottom=neighbor?.12+neighbor*.14:0;faces.push({x,y,side,from:neighbor,to:height,points:[[...a,bottom],[...b,bottom],[...b,top],[...a,top]]});}
  faces.push({x,y,side:4,from:height,to:height,points:corners.map(p=>[...p,top])});
 }return faces;
}
export function drawBuildingBlocks(ctx,d,rotation){const rot=((rotation%4)+4)%4,turn=(x,y)=>rot===0?[x,y]:rot===1?[-y,x]:rot===2?[-x,-y]:[y,-x],project=p=>projectBuildingPoint(p,rotation,d.footprint),tint=(hex,f)=>'#'+hex.slice(1).match(/../g).map(v=>Math.min(255,Math.round(parseInt(v,16)*f)).toString(16).padStart(2,'0')).join(''),polygon=(points,color)=>{ctx.beginPath();points.map(project).forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=color;ctx.fill();};
 for(const face of buildingBlockFaces(d.blocks,rot,d.footprint)){const material=d.materials?.[(face.y*10+face.x)*5+face.side]||0;polygon(face.points,tint(materialSurfaceColor(material,d),face.side===4?1.08:face.side%2?.72:.9));drawMaterialDetail(face,material,d,polygon);if(face.side===4||material===3||material===4)continue;const a=face.points[0],b=face.points[1],point=(f,z)=>[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f,z];for(let level=face.from;level<face.to;level++){const low=.12+(level+.23)*.14,high=.12+(level+.7)*.14;polygon([point(.23,low),point(.77,low),point(.77,high),point(.23,high)],(level*7+face.x*3+face.y+face.side)%9===0?d.accent:d.windows);}}
}
